// „ქართული გალობის ანთოლოგია“, the western volumes from vol. V on (vol. I is in anthologyChants.ts): V — R. Khundadze's
// liturgy in the Gurian-Imeretian „sada“ mode (1911) and Ph. Koridze's Pascha and great feasts. Only the versions the
// site's books lack, by chant id; read and compared by scripts/omr (see its README). The school is the Gelati row's „გ.ს.“
// (Khundadze's is a guess from the volume, as for vol. XXVIII). VI–VIII — the Heirmologion, Koridze's and Kereselidze's
// mss. Q684 (Anton Dumbadze), Q687 and Q689 (Aristo Kutateladze): each irmos in its tone (dz-1…8) or in the katavasia
// canon that has it with the same words; no tone given → „ხმა უცნობია“ (dz-a8-12); other kinds without a place of their own
// → „სხვა საგალობლები“ (dz-a6-1). An irmos sung to the same tune as a sticheron with other words is kept (its own words).
// IX — Kereselidze's Pascha (ms. Q692): Holy Saturday's matins → mx-20, the Paschal night → the ზატიკი items.
// XII–XIII — Kereselidze's ms. Q672: vespers → მწუხრი (the Resurrection troparia → ცისკარი), feast troparia → their feast
// (a saint the site lacked got a feast item with the book's old-style date), Triodion → მარხვანი / ზატიკი, the two
// paracleses → the tab „პარაკლისი“ (pr-1, pr-2). A troparion matched by notes stays unless it is the same chant or words.
// XIV–XVII — Kereselidze's ms. Q673, the vigil's matins: the midnight office's Trinity canons (irmoi → their tone), the
// opening of matins, sessional hymns, magnifications and matins prokeimena (→ their feast), evlogitaria, hypakoe, anabathmoi,
// the matins irmoi and katavasiai, exapostilaria (a new item), the praises' stichera (a new item), the end of matins, the
// first hour, Lent's alleluia and photagogika (→ მარხვანი); XVIII — ms. Q674, the Chrysostom liturgy (→ წირვა).
// XIX–XXI — Q674 goes on: the liturgy's plain styles, the Presanctified, Holy Week's liturgies (→ წირვა / მარხვანი), the feasts'
// liturgy chants (→ their feast), the Beatitudes' troparia (→ მომიხსენენი), the funeral, ordination and wedding (→ their tabs);
// XXII–XXIII — the whole Nativity and Holy Thursday services, each in five new parts (sd-a22-…, mx-a23-…).
// A piece: [number as printed, page, version]; its notes file is a<vol>/<file>.json in R2 (utils/notesBase.ts), the file from
// the number (16a = 1601 — ×100, so a letter never meets a plain number; a unit of several numbers "1–5" = its first number).
import type { AnthPiece } from './anthologyChants';

type P = [string, number, string?];
const fileOf = (num: string) => {
  const m = /^(\d+)([a-z]?)/.exec(num)!;
  return m[2] ? Number(m[1]) * 100 + m[2].charCodeAt(0) - 96 : Number(m[1]);
};
const pieces = (vol: number, ps: P[]): AnthPiece[] =>
  ps.map(([num, page, version = '']) => ({ vol, num, file: fileOf(num), page, version, source: version || undefined }));

